/* ═══════════════════════════════════════════════════════════════
   SKYLIGHT THEME — SkillyChatbot Frontend Override
   ═══════════════════════════════════════════════════════════════ */

:root {
  --sky-primary:    #4F46E5;
  --sky-secondary:  #7C3AED;
  --sky-accent:     #06B6D4;
  --sky-success:    #10B981;
  --sky-dark:       #0F172A;
  --sky-mid:        #1E293B;
  --sky-text:       #334155;
  --sky-muted:      #64748B;
  --sky-border:     #E2E8F0;
  --sky-bg:         #F8FAFC;
  --sky-white:      #FFFFFF;
  --sky-radius:     12px;
  --sky-radius-sm:  8px;
  --sky-shadow:     0 4px 24px rgba(79,70,229,.12);
  --sky-transition: .25s cubic-bezier(.4,0,.2,1);
}

/* ── Base ──────────────────────────────────────────────────── */
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
  background: var(--sky-bg) !important;
  color: var(--sky-text) !important;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--sky-primary); text-decoration: none; transition: color var(--sky-transition); }
a:hover { color: var(--sky-secondary); }

/* ── Navbar ────────────────────────────────────────────────── */
.header-section,
.navbar,
.nav-section {
  background: var(--sky-dark) !important;
  border-bottom: 1px solid rgba(255,255,255,.07) !important;
  box-shadow: 0 2px 20px rgba(0,0,0,.3) !important;
  backdrop-filter: blur(10px);
}

.navbar-brand img { filter: brightness(0) invert(1); }

.nav-link,
.navbar-nav .nav-link {
  color: rgba(255,255,255,.8) !important;
  font-weight: 500;
  font-size: .9rem;
  letter-spacing: .01em;
  transition: color var(--sky-transition);
}
.nav-link:hover,
.navbar-nav .nav-link:hover { color: #fff !important; }

.navbar-nav .nav-item.active .nav-link {
  color: var(--sky-accent) !important;
}

/* ── Hero / Banner ─────────────────────────────────────────── */
.banner-section,
.hero-section,
[class*="banner"] {
  background: linear-gradient(135deg, var(--sky-dark) 0%, var(--sky-mid) 50%, #1a1060 100%) !important;
  position: relative;
  overflow: hidden;
}

.banner-section::before,
.hero-section::before {
  content: '';
  position: absolute;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(79,70,229,.3) 0%, transparent 70%);
  top: -200px; right: -100px;
  pointer-events: none;
}

.banner-section::after,
.hero-section::after {
  content: '';
  position: absolute;
  width: 400px; height: 400px;
  background: radial-gradient(circle, rgba(6,182,212,.2) 0%, transparent 70%);
  bottom: -150px; left: -50px;
  pointer-events: none;
}

.banner-section h1,
.hero-section h1,
.banner-section .section-title,
.banner-section .hero-title {
  color: #fff !important;
  font-size: clamp(2rem, 5vw, 3.5rem) !important;
  font-weight: 800 !important;
  line-height: 1.2 !important;
  letter-spacing: -.02em;
}

.banner-section p,
.hero-section p,
.banner-section .section-subtitle {
  color: rgba(255,255,255,.75) !important;
  font-size: 1.1rem !important;
}

/* ── Buttons ───────────────────────────────────────────────── */
.btn-primary,
.ai--btn,
[class*="btn--primary"] {
  background: linear-gradient(135deg, var(--sky-primary), var(--sky-secondary)) !important;
  border: none !important;
  border-radius: 50px !important;
  padding: .65rem 1.75rem !important;
  font-weight: 600 !important;
  font-size: .9rem !important;
  letter-spacing: .02em !important;
  box-shadow: 0 4px 15px rgba(79,70,229,.4) !important;
  transition: all var(--sky-transition) !important;
  color: #fff !important;
}
.btn-primary:hover,
.ai--btn:hover,
[class*="btn--primary"]:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(79,70,229,.5) !important;
}

.btn-outline-primary {
  border: 2px solid var(--sky-primary) !important;
  color: var(--sky-primary) !important;
  border-radius: 50px !important;
  background: transparent !important;
  font-weight: 600 !important;
  transition: all var(--sky-transition) !important;
}
.btn-outline-primary:hover {
  background: var(--sky-primary) !important;
  color: #fff !important;
}

/* ── Cards ─────────────────────────────────────────────────── */
.card,
.i-card-sm,
.i-card-md,
.package-card,
.feature-card,
.pricing-card {
  border: 1px solid var(--sky-border) !important;
  border-radius: var(--sky-radius) !important;
  box-shadow: 0 2px 12px rgba(0,0,0,.06) !important;
  transition: transform var(--sky-transition), box-shadow var(--sky-transition) !important;
  background: var(--sky-white) !important;
}
.card:hover,
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--sky-shadow) !important;
}

/* ── Sections ──────────────────────────────────────────────── */
.section-title,
.section-heading,
h2.title {
  font-size: clamp(1.6rem, 3vw, 2.4rem) !important;
  font-weight: 800 !important;
  color: var(--sky-dark) !important;
  letter-spacing: -.02em;
}

.section-subtitle,
.section-desc {
  color: var(--sky-muted) !important;
  font-size: 1.05rem !important;
}

/* Accent underline on headings */
.section-title::after {
  content: '';
  display: block;
  width: 50px; height: 4px;
  background: linear-gradient(90deg, var(--sky-primary), var(--sky-accent));
  border-radius: 2px;
  margin: .75rem auto 0;
}

/* ── Feature icons / icon boxes ──────────────────────────── */
.icon-box,
.feature-icon {
  background: linear-gradient(135deg, rgba(79,70,229,.1), rgba(124,58,237,.1)) !important;
  border-radius: 14px !important;
  color: var(--sky-primary) !important;
}

/* ── Pricing / Plans ───────────────────────────────────────── */
.pricing-card.recommended,
.package-card.recommended,
.package-card.is-recommended {
  border-color: var(--sky-primary) !important;
  box-shadow: 0 8px 32px rgba(79,70,229,.2) !important;
  position: relative;
}
.pricing-card.recommended::before,
.package-card.recommended::before {
  content: 'Most Popular';
  position: absolute;
  top: -14px; left: 50%; transform: translateX(-50%);
  background: linear-gradient(135deg, var(--sky-primary), var(--sky-secondary));
  color: #fff;
  padding: 3px 18px;
  border-radius: 20px;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .05em;
  white-space: nowrap;
}

.package-price,
.plan-price {
  font-size: 2.8rem !important;
  font-weight: 800 !important;
  color: var(--sky-primary) !important;
}

/* ── Footer ────────────────────────────────────────────────── */
.footer-section,
footer {
  background: var(--sky-dark) !important;
  color: rgba(255,255,255,.7) !important;
  border-top: 1px solid rgba(255,255,255,.07) !important;
}
footer a, .footer-section a {
  color: rgba(255,255,255,.7) !important;
}
footer a:hover, .footer-section a:hover {
  color: #fff !important;
}
footer h5, footer h6, .footer-section h5, .footer-section h6 {
  color: #fff !important;
  font-weight: 700;
}

/* ── FAQ / Accordion ───────────────────────────────────────── */
.accordion-button {
  font-weight: 600 !important;
  color: var(--sky-dark) !important;
}
.accordion-button:not(.collapsed) {
  color: var(--sky-primary) !important;
  background: rgba(79,70,229,.05) !important;
  box-shadow: none !important;
}
.accordion-button::after {
  filter: invert(29%) sepia(85%) saturate(3000%) hue-rotate(240deg);
}

/* ── Badges ─────────────────────────────────────────────────── */
.badge-primary, .badge.bg-primary {
  background: linear-gradient(135deg, var(--sky-primary), var(--sky-secondary)) !important;
  border-radius: 50px !important;
  padding: .35em .8em !important;
  font-weight: 600 !important;
}

/* ── Forms ─────────────────────────────────────────────────── */
.form-control:focus,
.form-select:focus {
  border-color: var(--sky-primary) !important;
  box-shadow: 0 0 0 3px rgba(79,70,229,.15) !important;
}

/* ── Section alternating BG ─────────────────────────────── */
section:nth-child(even) {
  background: #F1F5F9;
}

/* ── Scroll-to-top btn ───────────────────────────────────── */
.scroll-top,
#scrollTop,
.back-to-top {
  background: linear-gradient(135deg, var(--sky-primary), var(--sky-secondary)) !important;
  border: none !important;
  border-radius: 50% !important;
  box-shadow: 0 4px 15px rgba(79,70,229,.4) !important;
  color: #fff !important;
}

/* ── Stats counters ─────────────────────────────────────── */
.counter-value,
.stat-number,
[class*="counter"] {
  font-weight: 800 !important;
  color: var(--sky-primary) !important;
}

/* ── Testimonials ───────────────────────────────────────── */
.testimonial-card,
.review-card {
  border-left: 4px solid var(--sky-primary) !important;
  border-radius: var(--sky-radius) !important;
  background: var(--sky-white) !important;
}

/* ── CTA / Call to action section ───────────────────────── */
.cta-section,
[class*="cta"] {
  background: linear-gradient(135deg, var(--sky-primary) 0%, var(--sky-secondary) 100%) !important;
  color: #fff !important;
  border-radius: var(--sky-radius) !important;
}
.cta-section h2, .cta-section h3,
[class*="cta"] h2, [class*="cta"] h3 {
  color: #fff !important;
}

/* ── Mobile responsive ───────────────────────────────────── */
@media (max-width: 768px) {
  .banner-section h1 { font-size: 2rem !important; }
  .section-title     { font-size: 1.6rem !important; }
  .package-price     { font-size: 2.2rem !important; }
}

