/* Skylight theme micro-interactions */
(function(){
  // Smooth entrance animations for cards
  if ('IntersectionObserver' in window) {
    const cards = document.querySelectorAll('.card, .feature-card, .package-card, .i-card-sm');
    const io = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          e.target.style.opacity = '1';
          e.target.style.transform = 'translateY(0)';
          io.unobserve(e.target);
        }
      });
    }, { threshold: 0.1 });
    cards.forEach(c => {
      c.style.opacity = '0';
      c.style.transform = 'translateY(20px)';
      c.style.transition = 'opacity .4s ease, transform .4s ease';
      io.observe(c);
    });
  }
})();
